SELECT * FROM (SELECT level, job_title, salary FROM employees)
PIVOT (MAX(salary) FOR job_title IN ('Intern', 'Designer', 'Director', 'Engineer'))
ORDER BY level;

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (MAX(rating) FOR country IN ('SG', 'UK', 'TH'))
ORDER BY city;

SELECT * FROM (SELECT status, method, amount FROM payments)
PIVOT (MAX(amount) FOR method IN ('bank_transfer', 'cash', 'card', 'promptpay'))
ORDER BY status;

SELECT * FROM (SELECT carrier, status, cost FROM shipments)
PIVOT (MAX(cost) FOR status IN ('IN_TRANSIT', 'LOST', 'RETURNED'))
ORDER BY carrier;

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (SUM(rating) FOR country IN ('DE', 'US', 'UK', 'SG'))
ORDER BY city;

SELECT * FROM (SELECT category, brand, cost FROM products)
PIVOT (SUM(cost) FOR brand IN ('Acme', 'Umbrella', 'Initech'))
ORDER BY category;

SELECT * FROM (SELECT page, event_type, duration_sec FROM web_events)
PIVOT (AVG(duration_sec) FOR event_type IN ('click', 'purchase', 'search', 'page_view'))
ORDER BY page;

SELECT * FROM (SELECT event_type, page, duration_sec FROM web_events)
PIVOT (AVG(duration_sec) FOR page IN ('/product', '/checkout', '/home'))
ORDER BY event_type;

SELECT * FROM (SELECT region, city, sqft FROM stores)
PIVOT (COUNT(sqft) FOR city IN ('London', 'Chiang Mai'))
ORDER BY region;

select * from (select order_id, status, cost from shipments)
pivot (sum(cost) for status in ('IN_TRANSIT', 'RETURNED', 'DELIVERED', 'LOST'))
order by order_id;

SELECT * FROM (SELECT job_title, level, salary FROM employees)
PIVOT (MAX(salary) FOR level IN ('L4', 'L3', 'L1'))
ORDER BY job_title;

select * from (select status, plan, monthly_fee from subscriptions)
pivot (avg(monthly_fee) for plan in ('standard', 'enterprise', 'premium', 'basic'))
order by status;

SELECT * FROM (SELECT customer_id, status, monthly_fee FROM subscriptions)
PIVOT (AVG(monthly_fee) FOR status IN ('ACTIVE', 'CANCELLED', 'PAUSED'))
ORDER BY customer_id;

SELECT * FROM (SELECT country, city, rating FROM suppliers)
PIVOT (SUM(rating) FOR city IN ('Singapore', 'Tokyo', 'Bangkok'))
ORDER BY country;

SELECT * FROM (SELECT location, dept_name, budget FROM departments)
PIVOT (COUNT(budget) FOR dept_name IN ('Marketing', 'Engineering'))
ORDER BY location;

SELECT * FROM (SELECT level, job_title, salary FROM employees)
PIVOT (SUM(salary) FOR job_title IN ('Analyst', 'Engineer', 'Director', 'Designer'))
ORDER BY level;

SELECT * FROM (SELECT status, method, amount FROM payments)
PIVOT (SUM(amount) FOR method IN ('promptpay', 'bank_transfer', 'card'))
ORDER BY status;

SELECT * FROM (SELECT event_type, page, duration_sec FROM web_events)
PIVOT (MAX(duration_sec) FOR page IN ('/search', '/home', '/checkout'))
ORDER BY event_type;

select * from (select status, carrier, cost from shipments)
pivot (max(cost) for carrier in ('FedEx', 'DHL'))
order by status;

SELECT * FROM (SELECT job_title, level, salary FROM employees)
PIVOT (COUNT(salary) FOR level IN ('L3', 'L4', 'L2'))
ORDER BY job_title;

SELECT c.id, c.city, c.country
FROM customers c
WHERE EXISTS (SELECT 1 FROM accounts a WHERE a.customer_id = c.id AND a.balance BETWEEN 29000 AND 42000);

SELECT s.id, s.city, s.sqft
FROM stores s
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.store_id = s.id AND o.shipping_fee <= 30);

SELECT d.id, d.location
FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);

select orders.id, orders.store_id, orders.discount
from orders
where exists (select 1 from order_items where order_items.order_id = orders.id and order_items.quantity = 6);

SELECT o.id, o.discount
FROM orders o
WHERE EXISTS (SELECT 1 FROM shipments s WHERE s.order_id = o.id);

SELECT d.id, d.budget, d.location
FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND LENGTH(e.full_name) >= 14);

SELECT p.id, p.stock_qty
FROM products p
WHERE EXISTS (SELECT 1 FROM order_items oi WHERE oi.product_id = p.id AND oi.order_id IN (12, 26, 30, 34));

SELECT o.id, o.shipping_fee, o.order_date
FROM orders o
WHERE EXISTS (SELECT 1 FROM payments p WHERE p.order_id = o.id AND p.amount <= 1190);

SELECT id, customer_id, COUNT(*) OVER (PARTITION BY customer_id) AS customer_id_count
FROM subscriptions
WHERE customer_id IS NOT NULL;

SELECT email, dept_id, hire_date
FROM employees
WHERE salary > 135000 AND manager_id IS NOT NULL;

SELECT device, browser
FROM sessions
WHERE country = 'TH' AND customer_id IS NOT NULL;

SELECT account_type, MAX(opened_date) AS latest_opened_date, MAX(opened_date) AS last_opened_date
FROM accounts
GROUP BY account_type;

SELECT id, event_time
FROM web_events
WHERE event_time < '2023-06-18' AND duration_sec = 183;

SELECT * FROM (SELECT city, region, sqft FROM stores WHERE LOWER(store_name) LIKE '%iam%')
PIVOT (MAX(sqft) FOR region IN ('West', 'North', 'East', 'South'))
ORDER BY city;

select round((100 * sum(case when country = 'DE' then 1 else 0 end)) / count(*), 1) as pct_de
from customers
where email like '%@startup.io' and (is_active or segment != 'Corporate');
